const defaults={version:1,profile:{name:'มินตรา',institution:'มหาวิทยาลัยศรีปทุม',major:'การสื่อสารและสื่อดิจิทัล',hours:8,mode:'ทุกแบบ'},skills:{communication:62,creative:58,analysis:43,digital:48,team:55},assessed:false,answers:[],applications:[],history:[],customJobs:[],saved:[],role:'student'};
const prototypeStorageKey=document.body.dataset?.demoCohort==='university'?'higher-prototype-university-v1':'higher-prototype-v1';
if(document.body.dataset?.demoCohort==='university')Object.assign(defaults.profile,{name:'ธนกฤต',institution:'มหาวิทยาลัยตัวอย่าง',major:'ระบบสารสนเทศ'});
let db=structuredClone(defaults);try{let parsed=JSON.parse(localStorage.getItem(prototypeStorageKey));if(parsed?.version===1)db={...db,...parsed,profile:{...defaults.profile,...parsed.profile},skills:{...defaults.skills,...parsed.skills}}}catch{}
let page=(location.hash.slice(1)||'roadmap');let selected='content',mapView='tree',zoom=.9,filter='all',query='',assessmentStep=0,assessmentStarted=false,feedbackRating=4,menuOpen=false;
function save(){try{localStorage.setItem(prototypeStorageKey,JSON.stringify(db))}catch{toast('เบราว์เซอร์ไม่อนุญาตให้บันทึก ข้อมูลจะอยู่เฉพาะการเปิดครั้งนี้')}}
function jobs(){return [...baseJobs,...db.customJobs]}
function completed(){return db.applications.filter(a=>a.status==='completed')}
function appFor(id){return db.applications.find(a=>a.jobId===id)}
function toast(message){$('#toast').className='toast';$('#toast').textContent=message;clearTimeout(toast.timer);toast.timer=setTimeout(()=>{$('#toast').className='';$('#toast').textContent=''},3800)}
const titles={home:'ภาพรวมของฉัน',roadmap:'เส้นทางของฉัน',jobs:'งานที่เหมาะกับฉัน',assessment:'สำรวจตัวเอง',work:'ประสบการณ์ของฉัน',profile:'โปรไฟล์และทักษะ',institution:'สำหรับสถานศึกษา',employer:'สำหรับผู้ว่าจ้าง'};
function navigate(to){location.hash=to;if(page===to)render();menuOpen=false}
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'roadmap';if(!titles[page])page='roadmap';filter='all';render();window.scrollTo(0,0)});
function btn(label,action,kind='',icon=''){return `<button class="btn ${kind}" ${action}>${icon?I(icon):''}${label}</button>`}
function shell(body){return `<div class="mobile-nav-backdrop ${menuOpen?'open':''}" data-action="menu"></div><aside class="sidebar ${menuOpen?'open':''}"><a class="brand" href="#home">${logo}<span>Higher</span></a><div class="side-caption">a little closer to your future.</div><div class="nav-label">YOUR JOURNEY</div><nav class="nav">${[['home','home','ภาพรวมของฉัน'],['map','roadmap','เส้นทางของฉัน'],['briefcase','jobs','งานที่เหมาะกับฉัน'],['clipboard','assessment','สำรวจตัวเอง'],['book','work','ประสบการณ์ของฉัน'],['user','profile','โปรไฟล์และทักษะ']].map(([ic,id,label])=>`<a href="#${id}" class="${page===id?'active':''}">${I(ic)}${label}${id==='jobs'?`<span class="count">${jobs().length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="side-note"><b>ไม่ต้องรู้คำตอบทั้งหมดในวันนี้</b>ลองทีละก้าว แล้วค่อยค้นพบเส้นทางที่เป็นคุณ</div><a class="profile-small" href="#profile"><div class="avatar">${esc(db.profile.name.slice(0,1))}</div><div><b>${esc(db.profile.name)}</b><small>${esc(db.profile.institution)}</small></div></a></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu" data-action="menu" aria-label="เปิดเมนู">${I('menu')}</button><span>พื้นที่ของฉัน</span><span>/</span><b>${titles[page]||titles.roadmap}</b></div><div class="top-actions"><div class="role-switch"><button data-role="student" class="${db.role==='student'?'active':''}">ผู้เรียน</button><button data-role="institution" class="${db.role==='institution'?'active':''}">สถานศึกษา</button><button data-role="employer" class="${db.role==='employer'?'active':''}">ผู้ว่าจ้าง</button></div><span class="demo-pill"><i class="dot"></i>ต้นแบบ · ข้อมูลจำลอง</span><button class="icon-button" data-action="notifications" aria-label="การแจ้งเตือน">${I('bell')}</button></div></header><div class="content">${body}</div></main>`}
function head(eye,title,desc,actions=''){return `<div class="page-head"><div><div class="eyebrow">${eye}</div><h1>${title}</h1><p>${desc}</p></div>${actions}</div>`}
function stats(){return `<div class="stats"><div class="stat"><div class="stat-icon">${I('map')}</div><div><small>เส้นทางที่เปิดให้สำรวจ</small><strong>3 <em>กลุ่มเส้นทาง</em></strong></div></div><div class="stat"><div class="stat-icon">${I('briefcase')}</div><div><small>งานทดลองในแพลตฟอร์ม</small><strong>${jobs().length} <em>งานจำลอง</em></strong></div></div><div class="stat"><div class="stat-icon">${I('check')}</div><div><small>ประสบการณ์ที่สำเร็จ</small><strong>${completed().length} <em>งาน</em></strong></div></div><div class="stat"><div class="stat-icon">${I('money')}</div><div><small>ค่าตอบแทนจากงานที่สำเร็จ</small><strong>${completed().reduce((sum,a)=>sum+(jobs().find(j=>j.id===a.jobId)?.pay||0),0).toLocaleString()} <em>บาท · จำลอง</em></strong></div></div></div>`}
