const edges=[['me','creative-base'],['me','business-base'],['me','tech-base'],['creative-base','content'],['creative-base','design'],['business-base','event'],['business-base','research'],['tech-base','data'],['tech-base','web'],['content','story'],['content','marketing'],['design','visual'],['event','marketing'],['research','marketing'],['research','analyst'],['data','analyst'],['web','product']];
function nodeState(n){if(n.type==='current')return 'current';if(n.job&&appFor(n.job)?.status==='completed')return 'done';const meets=Object.entries(n.requirements||{}).every(([k,v])=>db.skills[k]>=v);const evidence=!n.needs||n.needs.some(id=>appFor(id)?.status==='completed');return meets&&evidence?'ready':'future'}
function nodeVisible(n){return filter==='all'||n.id==='me'||n.branch===filter}
function tree(){return `<div class="map-stage" style="scale:${zoom}"><svg class="map-lines" viewBox="0 0 850 535" aria-hidden="true">${edges.map(([a,b])=>{const p=nodes.find(n=>n.id===a),q=nodes.find(n=>n.id===b);let status=nodeState(q);return `<path d="M${p.x} ${p.y-31} C ${p.x} ${(p.y+q.y)/2}, ${q.x} ${(p.y+q.y)/2}, ${q.x} ${q.y+32}" class="path ${status==='done'?'explored':status==='ready'?'ready':''}" style="opacity:${nodeVisible(p)&&nodeVisible(q)?1:.1}"/>`}).join('')}</svg><span class="branch-caption" style="left:91px">${I('pen')} สื่อและความคิดสร้างสรรค์</span><span class="branch-caption biz" style="left:365px">${I('people')} ธุรกิจและผู้คน</span><span class="branch-caption tech" style="left:641px">${I('code')} ดิจิทัลและข้อมูล</span>${nodes.map(n=>{const status=nodeState(n);return `<button class="node ${status} ${selected===n.id?'selected':''}" style="left:${n.x}px;top:${n.y}px;opacity:${nodeVisible(n)?1:.2}" data-node="${n.id}" aria-pressed="${selected===n.id}" aria-label="${n.title} ${status==='done'?'ผ่านประสบการณ์แล้ว':status==='future'?'เส้นทางที่ต้องพัฒนาต่อ':'เปิดสำรวจได้'}"><span class="node-top"><span class="node-icon">${I(status==='done'?'check':n.icon)}</span><b>${n.title}</b></span><small>${status==='done'?'ผ่านประสบการณ์แล้ว':status==='future'&&n.job?'เพิ่มทักษะก่อนเริ่ม':n.sub}</small>${status==='done'?'<span class="node-badge">สำเร็จแล้ว</span>':n.job&&status==='ready'?'<span class="node-badge">งานที่เริ่มได้</span>':''}</button>`}).join('')}</div>`}
function skillBars(requirements){return Object.entries(requirements).map(([k,target])=>{const score=db.skills[k];return `<div class="skill ${score>=target?'met':''}"><div class="skill-head"><span>${skillNames[k]}</span><span>${score} / ${target}</span></div><div class="track"><i style="width:${Math.min(100,score/target*100)}%"></i></div></div>`}).join('')}
function detail(){const n=nodes.find(n=>n.id===selected)||nodes[4],status=nodeState(n);let job=n.job&&jobs().find(j=>j.id===n.job);return `<div class="panel detail-panel"><div class="detail-main"><div class="eyebrow">EXPLORE YOUR PATH</div><div class="detail-icon">${I(n.icon)}</div><span class="detail-tag">${status==='current'?'จุดเริ่มต้นของคุณ':status==='done'?'มีประสบการณ์แล้ว':status==='ready'?'พร้อมสำรวจขั้นนี้':'เส้นทางที่พัฒนาต่อได้'}</span><h2>${n.title}</h2><p class="helper-text">${n.id==='me'?'คุณไม่จำเป็นต้องเลือกเพียงเส้นทางเดียว ทุกกิ่งเปิดให้ดูและเปลี่ยนเป้าหมายได้เมื่อรู้จักตัวเองมากขึ้น':job?esc(job.description):n.needs?'เป้าหมายการเติบโตระยะถัดไป สำรวจได้เสมอ แม้ยังต้องเพิ่มทักษะและสะสมประสบการณ์ก่อน':'ลองเริ่มจากงานเล็ก ๆ ในกลุ่มนี้ เพื่อค้นหาว่าสิ่งที่ชอบตรงกับสิ่งที่ได้ลงมือทำหรือไม่'}</p></div><div class="detail-secondary">${n.requirements?`<div class="section-label">ทักษะตอนนี้ / เป้าหมายตัวอย่าง</div>${skillBars(n.requirements)}`:''}${n.needs?`<div class="tip">${I('spark')} สะสมประสบการณ์จาก ${n.needs.map(id=>nodes.find(v=>v.id===id)?.title).join(' หรือ ')} แล้วกลับมาดูเส้นทางนี้อีกครั้ง</div>`:''}${job?`<div class="tip"><b>สิ่งที่เรียนที่นำมาใช้</b><br>${job.subjects}</div>${btn('ดูงานและค่าตอบแทน',`data-job="${job.id}"`,'primary','arrow')}`:n.next?.length?`<div class="section-label">ก้าวถัดไปที่เลือกได้</div>${n.next.map(id=>{const q=nodes.find(v=>v.id===id);return `<button class="btn full-width" data-node="${id}">${q.title}${I('chevron')}</button>`}).join('')}`:btn('สำรวจงานที่เริ่มได้',`data-go="jobs"`,'primary','briefcase')}<p class="note-under">เส้นทางและคะแนนเป็นตัวอย่างจากกติกาจำลอง ไม่ใช่ผลวัดความสามารถหรือคำตัดสินอนาคต</p></div></div>`}
function roadmap(){return head('YOUR PERSONAL ROADMAP','ทุกกิ่ง คือโอกาสที่เป็นไปได้','เริ่มจากสิ่งที่เป็นคุณ แล้วค่อย ๆ ค้นพบทางของตัวเอง',btn('สำรวจตัวเองใหม่',`data-go="assessment"`,'','spark'))+stats()+`<div class="map-layout"><section class="panel"><div class="panel-top"><div><h2>แผนที่เส้นทางของ ${esc(db.profile.name)}</h2><p>แตะที่แต่ละกิ่ง เพื่อดูทักษะและงานที่ลองทำได้</p></div><div class="segmented"><button class="${mapView==='tree'?'active':''}" data-view="tree">แผนผัง</button><button class="${mapView==='history'?'active':''}" data-view="history">การเปลี่ยนแปลง</button></div></div>${mapView==='tree'?`<div class="map-toolbar"><div class="legend"><span><i class="done"></i>ผ่านประสบการณ์แล้ว</span><span><i class="open"></i>เริ่มได้ตอนนี้</span><span><i class="later"></i>พัฒนาต่อได้</span></div><div class="map-controls"><button data-zoom="out" aria-label="ย่อแผนผัง">−</button><span>${Math.round(zoom*100)}%</span><button data-zoom="in" aria-label="ขยายแผนผัง">+</button><button data-zoom="fit" aria-label="จัดแผนผังให้พอดี">⌖</button></div></div><div class="map-viewport" id="map-viewport">${tree()}</div><div class="map-bottom"><span>${I('heart')} ไม่ต้องเลือกแค่กิ่งเดียว คุณลองได้หลายเส้นทาง</span><button class="btn ghost small" data-action="branch-filter">${filter==='all'?'ดูทุกเส้นทาง':'คืนค่าทุกเส้นทาง'} ${I('settings')}</button></div>`:`<div style="padding:25px">${historyContent()}</div>`}</section><aside id="node-detail">${detail()}</aside></div><div class="below-grid"><section class="panel"><div class="panel-top"><div><h2>ก้าวเล็ก ๆ ที่เริ่มได้วันนี้</h2><p>งานตัวอย่างที่เชื่อมกับสิ่งที่เรียน</p></div><a href="#jobs" class="helper-text">ดูทั้งหมด →</a></div><div class="mini-list">${rankedJobs().slice(0,2).map(j=>`<div class="mini-row"><div class="logo-tile">${j.initial}</div><div><b>${j.title}</b><p>${j.company} · ${j.place}</p></div><div class="right"><strong>฿${j.pay}</strong><p>ต่อ${j.unit}</p></div><button class="icon-button" data-job="${j.id}" aria-label="ดู ${j.title}">${I('arrow')}</button></div>`).join('')}</div></section><section class="panel"><div class="panel-top"><div><h2>เส้นทางที่ค่อย ๆ ชัดขึ้น</h2><p>ให้ประสบการณ์ช่วยคุณตัดสินใจ</p></div>${I('spark')}</div><div class="update-block"><div class="round-icon">${I(completed().length?'check':'heart')}</div><div><b>${completed().length?'อัปเดตจากงานที่คุณได้ลองแล้ว':'เริ่มจากการลอง ไม่ใช่การตัดสิน'}</b><p>${completed().length?'ผลประเมินจากผู้ว่าจ้างและสิ่งที่คุณรู้สึกหลังทำงาน ถูกนำมาปรับทักษะและแนะนำก้าวถัดไปแล้ว':'หลังจบงาน ให้ทั้งคุณและผู้ว่าจ้างสะท้อนประสบการณ์ แล้วดูว่ากิ่งไหนเริ่มชัดขึ้นสำหรับคุณ'}</p>${btn('ดูประสบการณ์ของฉัน',`data-go="work"`,'small')}</div></div></section></div>`}
function historyContent(){return db.history.length?db.history.slice().reverse().map(h=>`<div class="history-entry"><small>${esc(h.date)}</small><h3>${esc(h.title)}</h3><p>${esc(h.text)}</p>${h.changes?Object.entries(h.changes).map(([k,v])=>`<span class="pill pink">${skillNames[k]} +${v}</span> `).join(''):''}</div>`).join(''):`<div class="empty">${I('history')}<h3>เส้นทางยังรอเรื่องราวของคุณ</h3><p>ลองทำงานและสะท้อนประสบการณ์<br>การเปลี่ยนแปลงจะถูกบันทึกที่นี่</p>${btn('ดูงานที่เริ่มได้',`data-go="jobs"`,'primary')}</div>`}
function scoreJob(j){const keys=Object.keys(j.scores);return keys.reduce((s,k)=>s+db.skills[k],0)/keys.length}
function rankedJobs(){const latest=completed().at(-1);const previous=latest&&jobs().find(j=>j.id===latest.jobId);const score=j=>scoreJob(j)+(Number(db.profile.hours)>=j.hours?8:-15)+(db.profile.mode==='ทุกแบบ'||db.profile.mode===j.place?5:-10)+(previous&&latest.reflection?.feeling==='อยากสำรวจเส้นทางอื่น'&&previous.category!==j.category?12:0);return jobs().slice().sort((a,b)=>score(b)-score(a))}
function jobCard(j){const application=appFor(j.id),enoughTime=Number(db.profile.hours)>=j.hours;return `<article class="job-card"><div class="company"><div class="company-symbol">${esc(j.initial)}</div><button class="icon-button" data-save-job="${j.id}" aria-label="${db.saved.includes(j.id)?'เลิกบันทึก':'บันทึก'} ${esc(j.title)}" aria-pressed="${db.saved.includes(j.id)}" style="color:${db.saved.includes(j.id)?'var(--pink)':'#aba2b2'}">${I('heart')}</button></div><h3>${esc(j.title)}</h3><span class="company-name">${esc(j.company)} · องค์กรตัวอย่าง</span><div class="tags"><span class="pill">${esc(j.place)}</span><span class="pill">${j.hours} ชม.</span>${application?`<span class="pill green">${statusName(application.status)}</span>`:''}${!enoughTime?'<span class="pill">เกินเวลาที่ตั้งไว้</span>':''}</div><div class="reason">${I('spark')} เชื่อมกับ ${esc(j.subjects)}<br>ใช้ทักษะ ${j.skills.map(esc).join(' และ ')}</div><div class="job-foot"><span class="money">฿${j.pay.toLocaleString()} <small>/ ${esc(j.unit)}</small></span>${btn('ดูรายละเอียด',`data-job="${j.id}"`,'small','arrow')}</div></article>`}
function jobsPage(){let list=rankedJobs().filter(j=>(filter==='all'||(filter==='saved'?db.saved.includes(j.id):j.category===filter))&&`${j.title} ${j.company} ${j.subjects}`.toLowerCase().includes(query.toLowerCase()));return head('REAL WORK, SMALL STEPS','สิ่งที่เรียน ใช้ทำอะไรได้บ้าง','งานทั้งหมดเป็นตัวอย่างสำหรับทดลองใช้งาน ไม่มีการสมัครหรือจ่ายเงินจริง',btn('ไปดูเส้นทาง',`data-go="roadmap"`,'','map'))+`<div class="filters"><div class="search">${I('search')}<input id="job-search" placeholder="ค้นหางาน ทักษะ หรือสิ่งที่เรียน" value="${esc(query)}" aria-label="ค้นหางาน"></div>${[['all','ทั้งหมด'],['creative','สร้างสรรค์'],['business','ธุรกิจ'],['tech','ดิจิทัล'],['saved','บันทึกไว้']].map(([id,label])=>`<button class="filter-button ${filter===id?'active':''}" data-filter="${id}">${label}</button>`).join('')}</div><p class="helper-text">เรียงจากทักษะที่สอดคล้องกับโปรไฟล์จำลองของคุณ · เวลาและความสะดวกแสดงในรายละเอียด</p><div class="job-grid" id="job-results">${list.length?list.map(jobCard).join(''):`<div class="empty">${I('search')}<h3>ยังไม่พบงานที่ตรงกับตัวกรอง</h3><p>ลองเปลี่ยนคำค้น หรือเลือกดูงานทั้งหมด</p>${btn('ล้างตัวกรอง',`data-action="clear-filter"`,'soft')}</div>`}</div>`}
function home(){return head('A LITTLE CLOSER, EVERY DAY',`สวัสดี ${esc(db.profile.name)} ☀`,'วันนี้ไม่ต้องรู้ทุกคำตอบ แค่ได้ลองอีกหนึ่งก้าวก็พอ',btn('แก้ไขโปรไฟล์',`data-go="profile"`,'','user'))+`<section class="hero"><div><span class="welcome-tag">${I('spark')} YOUR NEXT CHAPTER</span><h2>อนาคตไม่ต้องเดา<br><em>ค่อย ๆ ลอง แล้วค่อยค้นพบ</em></h2><p>เห็นว่าสิ่งที่เรียนเชื่อมกับงานอะไรได้ ลองทำงานที่เหมาะกับเวลาของคุณ แล้วใช้ประสบการณ์ช่วยเลือกทางไปต่อ</p>${btn('สำรวจเส้นทางของฉัน',`data-go="roadmap"`,'primary','map')} ${btn('เริ่มประเมินตัวเอง',`data-go="assessment"`,'')}</div><div class="hero-steps"><div class="hero-step">${I('book')}สิ่งที่เรียน</div>${I('arrow')}<div class="hero-step">${I('briefcase')}งานที่ได้ลอง</div>${I('arrow')}<div class="hero-step">${I('map')}ทางที่เป็นคุณ</div></div></section>`+stats()+`<div class="section-head"><h2>ลองเริ่มจากงานเล็ก ๆ ที่เหมาะกับคุณ</h2><a href="#jobs" class="helper-text">ดูงานทั้งหมด →</a></div><div class="job-grid">${rankedJobs().slice(0,3).map(jobCard).join('')}</div><p class="key-note">ต้นแบบนี้ใช้กติกาจำลองแทน AI และเก็บข้อมูลเฉพาะในเบราว์เซอร์ของคุณ ไม่มีการยืนยันตัวตน สมัครงาน หรือชำระเงินจริง</p>`}
const questions=[
 {title:'ถ้ามีเวลาลองทำอะไรสักอย่าง คุณอยากเริ่มจากอะไร?',options:[['เขียนเรื่องหรือออกแบบภาพ',{creative:8,communication:5}],['ช่วยคนและจัดกิจกรรม',{team:8,communication:5}],['ลองเครื่องมือดิจิทัลใหม่ ๆ',{digital:8,analysis:4}],['ค้นข้อมูลเพื่อหาคำตอบ',{analysis:8,digital:4}]]},
 {title:'งานกลุ่มแบบไหนที่คุณรู้สึกเป็นตัวเอง?',options:[['เสนอไอเดียและเล่าเรื่องให้เพื่อนเข้าใจ',{creative:6,communication:7}],['ประสานงานให้ทุกคนทำงานร่วมกัน',{team:8,communication:4}],['ลงมือทำชิ้นงานด้วยเครื่องมือ',{digital:8,creative:3}],['วางแผนและตรวจรายละเอียด',{analysis:8,team:3}]]},
 {title:'เมื่อเจอปัญหาที่ไม่เคยทำ คุณมักเริ่มอย่างไร?',options:[['หาตัวอย่างและทดลองทำเอง',{digital:6,analysis:4}],['คุยกับคนอื่นเพื่อหามุมใหม่',{communication:6,team:6}],['แยกปัญหาเป็นขั้นตอนเล็ก ๆ',{analysis:8}],['ลองคิดวิธีที่ต่างจากเดิม',{creative:8}]]},
 {title:'วิชาหรือกิจกรรมไหนที่คุณอยากนำไปใช้จริง?',options:[['ภาษา การสื่อสาร และสื่อ',{communication:8,creative:3}],['ศิลปะและการออกแบบ',{creative:8,digital:3}],['คณิตศาสตร์และการวิเคราะห์',{analysis:8}],['คอมพิวเตอร์และเทคโนโลยี',{digital:8}]]},
 {title:'คุณอยากลองงานครั้งแรกแบบไหน?',options:[['มีโจทย์ชัดและมีพี่เลี้ยงช่วย',{team:5,analysis:3}],['ได้ใช้ไอเดียของตัวเอง',{creative:7}],['ได้พูดคุยกับผู้คน',{communication:7,team:4}],['ได้ใช้เครื่องมือและจัดการข้อมูล',{digital:6,analysis:5}]]},
 {title:'สิ่งไหนสำคัญที่สุดสำหรับคุณตอนนี้?',options:[['อยากรู้ว่าตัวเองถนัดอะไร',{}],['อยากหารายได้ควบคู่กับเรียน',{}],['อยากมีผลงานสำหรับอนาคต',{}],['อยากเห็นว่าสิ่งที่เรียนใช้ทำอะไรได้',{}]]},
 {title:'คุณสะดวกให้เวลากับงานทดลองแค่ไหน?',options:[['ประมาณ 4 ชั่วโมงต่อสัปดาห์',{},4],['ประมาณ 6 ชั่วโมงต่อสัปดาห์',{},6],['ประมาณ 8 ชั่วโมงต่อสัปดาห์',{},8],['ประมาณ 12 ชั่วโมงต่อสัปดาห์',{},12]]},
 {title:'คุณสะดวกทำงานรูปแบบไหน?',options:[['ออนไลน์เป็นหลัก',{},'ออนไลน์'],['ภายในสถานศึกษา',{},'ในสถานศึกษา'],['สะดวกทั้งสองแบบ',{},'ทุกแบบ']]}
];
function assessment(){if(!assessmentStarted)return head('DISCOVER YOURSELF','เริ่มจากการรู้จักตัวเอง','ไม่มีคำตอบที่ผิด และผลครั้งเดียวไม่ได้กำหนดอนาคตของคุณ')+`<div class="assessment-shell panel assessment-intro"><div class="detail-icon">${I('spark')}</div><h2>ลองฟังตัวเอง ก่อนเลือกทางถัดไป</h2><p>แบบสำรวจตัวอย่าง 8 ข้อ ช่วยสะท้อนความสนใจ วิธีทำงาน และเงื่อนไขชีวิต เพื่อทดลองจัดอันดับงานและสร้างเส้นทางเริ่มต้น</p><div class="tip">ต้นแบบนี้ใช้กติกาคะแนนที่เขียนไว้ในโค้ด ยังไม่ได้เชื่อมโมเดล AI หรือแบบประเมินที่ผ่านการตรวจสอบทางวิชาการ</div><div class="form-grid"><label class="field"><span>ชื่อที่อยากให้เราเรียก</span><input id="assess-name" value="${esc(db.profile.name)}" maxlength="40"></label><label class="field"><span>สิ่งที่กำลังเรียน</span><input id="assess-major" value="${esc(db.profile.major)}" maxlength="100"></label></div><label class="check-row"><input id="assessment-consent" type="checkbox">ฉันเข้าใจว่าเป็นข้อมูลจำลอง และยินยอมให้บันทึกคำตอบในเบราว์เซอร์เครื่องนี้</label><div class="spacer"></div>${btn(db.assessed?'ประเมินใหม่':'เริ่มสำรวจตัวเอง',`data-action="start-assessment"`,'primary','arrow')}<p class="helper-text">ไม่ต้องกรอกข้อมูลจริง ไม่ส่งข้อมูลออกนอกเครื่อง และรีเซ็ตข้อมูลได้ในหน้าโปรไฟล์</p></div>`;const q=questions[assessmentStep];return head('DISCOVER YOURSELF','พื้นที่เล็ก ๆ สำหรับสำรวจตัวเอง','คำตอบเปลี่ยนได้ เช่นเดียวกับเส้นทางของคุณ')+`<div class="assessment-shell panel assessment-step"><div class="step-progress">${questions.map((_,i)=>`<i class="${i<=assessmentStep?'on':''}"></i>`).join('')}</div><span class="question-number">ข้อ ${assessmentStep+1} จาก ${questions.length}</span><h2>${q.title}</h2><p class="hint">เลือกคำตอบที่ใกล้กับคุณที่สุดในตอนนี้</p><div class="options">${q.options.map(([text],i)=>`<button class="option ${db.answers[assessmentStep]===i?'active':''}" data-answer="${i}" aria-pressed="${db.answers[assessmentStep]===i}"><span class="radio"></span>${text}</button>`).join('')}</div><div class="assessment-footer">${btn(assessmentStep?'ย้อนกลับ':'พักไว้ก่อน',`data-action="prev-question"`)}<button class="btn primary" data-action="next-question" ${Number.isInteger(db.answers[assessmentStep])?'':'disabled'}>${assessmentStep===questions.length-1?'ดูผลและเส้นทาง':'ถัดไป'} ${I('arrow')}</button></div></div>`}
function statusName(s){return {applied:'รอการตอบรับ',accepted:'พร้อมเริ่มงาน',submitted:'ส่งผลงานแล้ว',reviewed:'รอสะท้อนประสบการณ์',completed:'สำเร็จแล้ว'}[s]||s}
function work(){return head('LEARN BY DOING','ทุกประสบการณ์ ทำให้รู้จักตัวเองมากขึ้น','ติดตามการลองงาน และนำสิ่งที่ได้เรียนรู้กลับมาอัปเดตเส้นทาง',btn('หางานที่อยากลอง',`data-go="jobs"`,'primary','briefcase'))+(db.applications.length?db.applications.slice().reverse().map(a=>{const j=jobs().find(j=>j.id===a.jobId);if(!j)return '';const order=['applied','accepted','submitted','reviewed','completed'];const current=order.indexOf(a.status);return `<section class="panel work-card"><div class="work-top"><div><span class="pill ${a.status==='completed'?'green':'pink'}">${statusName(a.status)}</span><h3 style="margin-top:9px">${esc(j.title)}</h3><p>${esc(j.company)} · ${esc(j.duration)} · ค่าตอบแทนตัวอย่าง ฿${j.pay} / ${j.unit}</p></div>${btn('รายละเอียดงาน',`data-job="${j.id}"`,'small')}</div><div class="work-steps">${['สมัคร','ตอบรับ','ส่งผลงาน','ผู้ว่าจ้างประเมิน','สะท้อนและอัปเดต'].map((label,i)=>`<span class="${i<=current?'on':''}">${label}</span>`).join('')}</div>${a.evidence?`<p><b>ผลงานที่บันทึก:</b> ${esc(a.evidence)}</p>`:''}${a.employerFeedback?`<p><b>ความเห็นผู้ว่าจ้าง:</b> ${esc(a.employerFeedback.comment)} (${a.employerFeedback.rating}/5)</p>`:''}${a.reflection?`<p><b>สิ่งที่คุณค้นพบ:</b> ${esc(a.reflection.note)} · ${esc(a.reflection.feeling)}</p>`:''}<div class="work-actions">${a.status==='applied'?btn('จำลองผู้ว่าจ้างตอบรับ',`data-accept="${j.id}"`,'soft','check'):a.status==='accepted'?btn('ส่งผลงานตัวอย่าง',`data-submit="${j.id}"`,'primary','clipboard'):a.status==='submitted'?btn('เปิดหน้าผู้ว่าจ้างเพื่อประเมิน',`data-role="employer"`,'soft','briefcase'):a.status==='reviewed'?btn('สะท้อนประสบการณ์และอัปเดตเส้นทาง',`data-reflect="${j.id}"`,'primary','spark'):btn('ดู Roadmap ที่อัปเดต',`data-go="roadmap"`,'soft','map')}</div><p class="helper-text">ขั้นตอนและค่าตอบแทนทั้งหมดเป็นการจำลอง ไม่มีการส่งงานหรือชำระเงินจริง</p></section>`}).join(''):`<section class="panel empty">${I('briefcase')}<h3>เรื่องราวบทแรกของคุณยังรออยู่</h3><p>เริ่มจากเลือกงานที่อยากลอง แล้วดูว่าคุณค้นพบอะไรจากการลงมือทำ</p>${btn('ไปดูงานแนะนำ',`data-go="jobs"`,'primary','arrow')}</section>`)}
function profile(){return head('THIS IS YOU','ตัวตนที่เปลี่ยนและเติบโตได้','ข้อมูลนี้เป็นของคุณ แก้ไขหรือเริ่มใหม่ได้เสมอ',btn('ดาวน์โหลดข้อมูล',`data-action="export"`,'','download'))+`<div class="profile-grid"><section class="panel profile-card"><div class="profile-intro"><div class="avatar">${esc(db.profile.name.slice(0,1))}</div><div><h2>${esc(db.profile.name)}</h2><p>${esc(db.profile.institution)}</p></div></div><form id="profile-form"><label class="field"><span>ชื่อที่ใช้แสดง</span><input name="name" value="${esc(db.profile.name)}" maxlength="40" required></label><label class="field"><span>สถานศึกษา (ข้อมูลจำลอง)</span><input name="institution" value="${esc(db.profile.institution)}" maxlength="100" required></label><label class="field"><span>สาขาหรือสิ่งที่กำลังเรียน</span><input name="major" value="${esc(db.profile.major)}" maxlength="100" required></label><div class="form-grid"><label class="field"><span>เวลาที่สะดวกต่อสัปดาห์</span><select name="hours">${[4,6,8,12].map(v=>`<option value="${v}" ${Number(db.profile.hours)===v?'selected':''}>${v} ชั่วโมง</option>`).join('')}</select></label><label class="field"><span>รูปแบบงาน</span><select name="mode">${['ทุกแบบ','ออนไลน์','ในสถานศึกษา'].map(v=>`<option ${db.profile.mode===v?'selected':''}>${v}</option>`).join('')}</select></label></div><button class="btn primary" type="submit">บันทึกโปรไฟล์ ${I('check')}</button></form></section><section class="panel profile-card skills-profile"><h2>ทักษะที่กำลังเติบโต</h2><p class="helper-text">${db.assessed?'อัปเดตจากคำตอบและประสบการณ์ในต้นแบบ':'คะแนนเริ่มต้นจากโปรไฟล์ตัวอย่าง ยังไม่ได้ทำแบบสำรวจ'}</p>${Object.entries(skillNames).map(([k,label])=>`<div class="skill"><div class="skill-head"><span>${label}</span><span>${db.skills[k]} / 100</span></div><div class="track"><i style="width:${db.skills[k]}%"></i></div></div>`).join('')}<div class="tip">คะแนนเป็นเพียงตัวอย่างเพื่อสาธิตการเปลี่ยนเส้นทาง ไม่ใช่คะแนนวัดความฉลาดหรือความสามารถจริง</div>${btn('สำรวจตัวเองใหม่',`data-go="assessment"`,'soft','spark')}<div class="spacer"></div><p class="helper-text">ข้อมูลเก็บใน localStorage ของเบราว์เซอร์นี้ ไม่แชร์ข้ามผู้ใช้หรืออุปกรณ์ และยังไม่มีการยืนยันตัวตนผ่านสถานศึกษาจริง</p>${btn('รีเซ็ตข้อมูลต้นแบบ',`data-action="reset"`,'small')}</section></div>`}
function institution(){return head('INSTITUTION WORKSPACE','มองเห็นการเติบโตของผู้เรียน','มุมมองสถานศึกษาจำลอง แสดงข้อมูลจากการทดลองในเบราว์เซอร์นี้',btn('กลับมุมมองผู้เรียน',`data-role="student"`,'','user'))+stats()+`<section class="panel"><div class="panel-top"><div><h2>ติดตามผู้เรียนรายบุคคล</h2><p>ไม่มีการเชื่อมระบบทะเบียนหรือข้อมูลนักเรียนจริง</p></div><span class="pill pink">ข้อมูลจำลอง</span></div><div class="table-wrap"><table><thead><tr><th>ผู้เรียน / สถานศึกษา</th><th>แบบประเมิน</th><th>งานที่สมัคร</th><th>ประสบการณ์สำเร็จ</th><th>การติดตาม</th></tr></thead><tbody><tr><td><b>${esc(db.profile.name)}</b><p class="helper-text">${esc(db.profile.institution)}</p></td><td><span class="pill ${db.assessed?'green':''}">${db.assessed?'ทำแล้ว':'ยังไม่ประเมิน'}</span></td><td>${db.applications.length} งาน</td><td>${completed().length} งาน</td><td>${btn('ดูเส้นทาง',`data-go="roadmap"`,'small')}${btn('บันทึกคำแนะนำ',`data-action="advisor-note"`,'small')}</td></tr></tbody></table></div></section><div class="below-grid"><section class="panel profile-card"><h2>สิ่งที่สถานศึกษาช่วยได้</h2><p class="helper-text">ใช้ข้อมูลประกอบการพูดคุยกับผู้เรียน ตรวจสอบความเหมาะสมของงาน และช่วยวางแผนเวลาให้ไม่กระทบการเรียน ข้อมูลชุดนี้ไม่เพียงพอสำหรับสรุปความเสี่ยงหลุดจากระบบ</p>${db.advisorNote?`<div class="tip"><b>บันทึกคำแนะนำ</b><br>${esc(db.advisorNote)}</div>`:''}</section><section class="panel profile-card"><h2>พัฒนาการล่าสุด</h2>${historyContent()}</section></div>`}
function employer(){return head('EMPLOYER WORKSPACE','โอกาสเล็ก ๆ ที่สร้างการเติบโต','มุมมองผู้ว่าจ้างจำลอง งานที่เพิ่มจะอยู่ในเบราว์เซอร์นี้เท่านั้น',btn('เพิ่มงานทดลอง',`data-action="new-job"`,'primary','briefcase'))+`<section class="panel"><div class="panel-top"><div><h2>ผู้สมัครและงานที่กำลังดำเนินการ</h2><p>เปลี่ยนบทบาทเพื่อสาธิตการตอบรับและให้ผลประเมิน</p></div><span class="pill">${db.applications.length} รายการ</span></div>${db.applications.length?`<div class="table-wrap"><table><thead><tr><th>งาน / ผู้สมัคร</th><th>สถานะ</th><th>ขั้นตอนถัดไป</th></tr></thead><tbody>${db.applications.map(a=>{const j=jobs().find(j=>j.id===a.jobId);if(!j)return '';return `<tr><td><b>${esc(j.title)}</b><p class="helper-text">${esc(db.profile.name)} · ${esc(db.profile.major)}</p>${a.evidence?`<p class="helper-text">ผลงาน: ${esc(a.evidence)}</p>`:''}</td><td><span class="pill ${a.status==='completed'?'green':'pink'}">${statusName(a.status)}</span></td><td>${a.status==='applied'?btn('ตอบรับผู้สมัคร',`data-accept="${j.id}"`,'small primary'):a.status==='submitted'?btn('ประเมินผลงาน',`data-review="${j.id}"`,'small primary'):a.status==='accepted'?'<span class="helper-text">รอผู้เรียนส่งผลงาน</span>':a.status==='reviewed'?'<span class="helper-text">รอผู้เรียนสะท้อนประสบการณ์</span>':'<span class="pill green">ประเมินครบแล้ว</span>'}</td></tr>`}).join('')}</tbody></table></div>`:`<div class="empty">${I('people')}<h3>ยังไม่มีผู้สมัครตัวอย่าง</h3><p>ไปที่มุมมองผู้เรียน เลือกสมัครงานเพื่อทดลองขั้นตอนนี้</p>${btn('เลือกงานทดลอง',`data-role="student" data-go="jobs"`,'soft')}</div>`}</section><div class="section-head"><h2>งานตัวอย่างทั้งหมด</h2></div><div class="job-grid">${jobs().map(jobCard).join('')}</div>`}
function render(){if(!titles[page])page='roadmap';$('#app').innerHTML=shell(({home,roadmap,jobs:jobsPage,assessment,work,profile,institution,employer}[page])());if(page==='roadmap'&&mapView==='tree'){const el=$('#map-viewport');requestAnimationFrame(()=>{if(el&&el.clientWidth<850*zoom)el.scrollLeft=(850*zoom-el.clientWidth)/2})}}
function modal(title,body,foot=''){closeModal();$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${title}</h2><button class="icon-button" data-action="close-modal" aria-label="ปิด">${I('close')}</button></div><div class="modal-body">${body}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}</section></div>`;const focusable=$('#overlay').querySelector('button,input,select,textarea');focusable?.focus();document.body.style.overflow='hidden'}
function closeModal(){$('#overlay').innerHTML='';document.body.style.overflow=''}
function showJob(id){const j=jobs().find(v=>v.id===id);if(!j)return;const a=appFor(id),enoughTime=db.profile.hours>=j.hours;modal('งานที่คุณเริ่มลองได้',`<span class="pill pink">โอกาสงานจำลอง</span><h3>${esc(j.title)}</h3><p>${esc(j.company)} · องค์กรตัวอย่าง</p><p>${esc(j.description)}</p><div class="job-facts"><div><small>ค่าตอบแทนตัวอย่าง</small><b>฿${j.pay.toLocaleString()} / ${esc(j.unit)}</b></div><div><small>รูปแบบงาน</small><b>${esc(j.place)}</b></div><div><small>เวลาที่ใช้</small><b>${esc(j.duration)}</b></div><div><small>เวลาที่คุณตั้งไว้</small><b>${db.profile.hours} ชม. / สัปดาห์</b></div></div>${!enoughTime?'<div class="tip">งานนี้ใช้เวลาเกินที่คุณตั้งไว้ ลองพิจารณาว่าจะกระทบการเรียนหรือไม่ ก่อนสมัคร</div>':''}${db.profile.mode!=='ทุกแบบ'&&db.profile.mode!==j.place?'<div class="tip">รูปแบบสถานที่ทำงานนี้ต่างจากความสะดวกที่คุณตั้งไว้</div>':''}<div class="section-label">สิ่งที่ได้ลองทำ</div><ul class="modal-list">${j.tasks.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><div class="tip"><b>สิ่งที่เรียนเกี่ยวข้องอย่างไร?</b><br>${esc(j.subjects)} ช่วยให้คุณนำพื้นฐานมาใช้กับโจทย์นี้ได้<br>ทักษะที่ใช้: ${j.skills.map(esc).join(' และ ')}</div><p class="helper-text">ผู้ว่าจ้างและงานเป็นข้อมูลจำลอง การกดสมัครไม่ส่งข้อมูลไปภายนอก และไม่มีการจ่ายเงินจริง</p>`,btn('ปิด',`data-action="close-modal"`)+btn(a?'ดูสถานะงานของฉัน':'สมัครงานตัวอย่างนี้',a?'data-action="my-work"':`data-apply="${id}"`,'primary','arrow'))}
function finishAssessment(){const skill={communication:35,creative:35,analysis:35,digital:35,team:35};questions.slice(0,6).forEach((q,i)=>{const choice=q.options[db.answers[i]];if(choice)Object.entries(choice[1]).forEach(([k,v])=>skill[k]+=v)});completed().forEach(a=>Object.entries(a.changes||{}).forEach(([k,v])=>skill[k]+=v));Object.keys(skill).forEach(k=>skill[k]=Math.min(95,skill[k]));db.skills=skill;db.profile.hours=questions[6].options[db.answers[6]][2];db.profile.mode=questions[7].options[db.answers[7]][2];db.assessed=true;db.history.push({date:new Date().toLocaleDateString('th-TH'),title:'รู้จักตัวเองอีกนิดจากแบบสำรวจ',text:'อัปเดตโปรไฟล์จากคำตอบและเงื่อนไขการทำงาน โดยยังเปิดให้สำรวจได้ทุกเส้นทาง'});save();assessmentStarted=false;selected=rankedJobs()[0].node;mapView='tree';navigate('roadmap');toast('สำรวจเสร็จแล้ว ลองกดแต่ละกิ่งเพื่อดูเส้นทางที่เป็นไปได้')}
function newJob(){modal('เพิ่มโอกาสงานตัวอย่าง',`<form id="new-job-form"><div class="form-grid"><label class="field"><span>ชื่องาน</span><input name="title" required maxlength="70" placeholder="เช่น ผู้ช่วยถ่ายภาพสินค้า"></label><label class="field"><span>ชื่อองค์กรจำลอง</span><input name="company" required maxlength="60"></label><label class="field"><span>กลุ่มงาน</span><select name="category"><option value="creative">สร้างสรรค์</option><option value="business">ธุรกิจและผู้คน</option><option value="tech">ดิจิทัลและข้อมูล</option></select></label><label class="field"><span>ค่าตอบแทนต่อชิ้นงาน (บาท)</span><input name="pay" type="number" min="1" max="100000" value="600" required></label><label class="field"><span>เวลาประมาณ (ชั่วโมง)</span><input name="hours" type="number" min="1" max="40" value="4" required></label><label class="field"><span>รูปแบบงาน</span><select name="place"><option>ออนไลน์</option><option>ในสถานศึกษา</option></select></label></div><label class="field"><span>รายละเอียดงานและสิ่งที่ได้ลองทำ</span><textarea name="description" maxlength="500" required></textarea></label><p class="helper-text">งานใหม่จะปรากฏในรายการงานแนะนำ ไม่เพิ่มกิ่งใหม่อัตโนมัติใน Roadmap ต้นแบบ</p><button class="btn primary" type="submit">บันทึกงานตัวอย่าง</button></form>`)}
document.addEventListener('click',e=>{
 const t=e.target.closest('button,a');if(!t){if(e.target.classList.contains('modal-backdrop'))closeModal();return}
 if(t.dataset.go){if(t.dataset.role){db.role=t.dataset.role;save()}closeModal();navigate(t.dataset.go);return}
 if(t.dataset.role){db.role=t.dataset.role;save();navigate(t.dataset.role==='student'?'home':t.dataset.role);return}
 if(t.dataset.node){const vp=$('#map-viewport'),left=vp?.scrollLeft||0,top=vp?.scrollTop||0;selected=t.dataset.node;const panel=$('#node-detail');if(panel)panel.innerHTML=detail();document.querySelectorAll('[data-node]').forEach(el=>el.classList.toggle('selected',el.dataset.node===selected&&el.classList.contains('node')));if(vp){vp.scrollLeft=left;vp.scrollTop=top}return}
 if(t.dataset.job){showJob(t.dataset.job);return}
 if(t.dataset.saveJob){const id=t.dataset.saveJob;db.saved=db.saved.includes(id)?db.saved.filter(v=>v!==id):[...db.saved,id];save();render();toast(db.saved.includes(id)?'บันทึกงานที่สนใจแล้ว':'นำออกจากงานที่บันทึกแล้ว');return}
 if(t.dataset.filter){filter=t.dataset.filter;render();return}
 if(t.dataset.zoom){const vp=$('#map-viewport');zoom=t.dataset.zoom==='fit'?Math.max(.45,Math.min(1,(vp.clientWidth-15)/850)):Math.max(.45,Math.min(1.35,zoom+(t.dataset.zoom==='in'?.1:-.1)));const before=vp.scrollLeft;const stage=$('.map-stage');stage.style.scale=zoom;$('.map-controls span').textContent=Math.round(zoom*100)+'%';vp.scrollLeft=t.dataset.zoom==='fit'?0:before;return}
 if(t.dataset.view){mapView=t.dataset.view;render();return}
 if(t.dataset.answer!==undefined){db.answers[assessmentStep]=Number(t.dataset.answer);save();render();return}
 if(t.dataset.apply){if(appFor(t.dataset.apply)){toast('สมัครงานนี้แล้ว');return}db.applications.push({jobId:t.dataset.apply,status:'applied',date:new Date().toISOString()});save();closeModal();navigate('work');toast('บันทึกการสมัครจำลองแล้ว ลองขั้นตอนตอบรับและส่งงานต่อได้');return}
 if(t.dataset.accept){let a=appFor(t.dataset.accept);if(a?.status==='applied'){a.status='accepted';save();render();toast('จำลองการตอบรับแล้ว ผู้เรียนสามารถส่งผลงานได้')}return}
 if(t.dataset.submit){modal('บันทึกผลงานตัวอย่าง',`<form id="evidence-form" data-job-id="${t.dataset.submit}"><p class="helper-text">พิมพ์สรุปสิ่งที่คุณได้ลองทำ หรือใช้ข้อความตัวอย่าง ไม่ส่งข้อมูลไปผู้ว่าจ้างจริง</p><label class="field"><span>ผลงานและสิ่งที่ทำ</span><textarea name="evidence" required maxlength="1000" placeholder="เช่น ออกแบบโพสต์ 3 ชิ้น ทดลองเขียนข้อความ และปรับงานตามโจทย์"></textarea></label><button class="btn primary" type="submit">ส่งผลงานจำลอง</button></form>`);return}
 if(t.dataset.review){feedbackRating=4;modal('ผลประเมินจากผู้ว่าจ้าง (จำลอง)',`<form id="review-form" data-job-id="${t.dataset.review}"><p class="helper-text">คะแนนนี้ใช้สาธิตการปรับทักษะ ไม่ใช่การรับรองผลงานจริง</p><div class="section-label">คุณภาพงานและการทำงานร่วมกัน</div><div class="feedback-stars">${[1,2,3,4,5].map(v=>`<button type="button" data-rating="${v}" class="${v===4?'active':''}">${v} ★</button>`).join('')}</div><label class="field"><span>สิ่งที่ทำได้ดีและสิ่งที่อยากให้ลองเพิ่ม</span><textarea name="comment" maxlength="1000" required placeholder="เช่น สื่อสารแนวคิดชัดเจน และปรับงานตามข้อเสนอแนะได้ดี"></textarea></label><button class="btn primary" type="submit">บันทึกผลประเมินจำลอง</button></form>`);return}
 if(t.dataset.rating){feedbackRating=Number(t.dataset.rating);$('.feedback-stars').querySelectorAll('button').forEach(b=>b.classList.toggle('active',Number(b.dataset.rating)===feedbackRating));return}
 if(t.dataset.reflect){modal('ลองแล้ว คุณรู้สึกอย่างไร?',`<form id="reflection-form" data-job-id="${t.dataset.reflect}"><p class="helper-text">ความรู้สึกของคุณสำคัญพอ ๆ กับผลงาน เส้นทางจะไม่ถูกกำหนดจากคะแนนของผู้ว่าจ้างเพียงด้านเดียว</p><label class="field"><span>อยากลองงานแนวนี้ต่อไหม?</span><select name="feeling"><option value="ชอบและอยากลองต่อ">ชอบและอยากลองต่อ</option><option value="ยังไม่แน่ใจ">ยังไม่แน่ใจ อยากลองอีกแบบ</option><option value="อยากสำรวจเส้นทางอื่น">ไม่ค่อยชอบ อยากสำรวจเส้นทางอื่น</option></select></label><label class="field"><span>ค้นพบอะไรเกี่ยวกับตัวเอง?</span><textarea name="note" maxlength="1000" required placeholder="เช่น ชอบการเล่าเรื่อง แต่ยังต้องฝึกใช้เครื่องมือออกแบบ"></textarea></label><button class="btn primary" type="submit">บันทึกและอัปเดต Roadmap ${I('spark')}</button></form>`);return}
 switch(t.dataset.action){
 case 'menu':menuOpen=!menuOpen;render();break;
 case 'close-modal':closeModal();break;
 case 'notifications':modal('อัปเดตของคุณ',`<div class="history-entry"><h3>ยินดีต้อนรับสู่ Higher</h3><p>ลองกดกิ่งใน Roadmap สำรวจงาน และบันทึกประสบการณ์แรกของคุณ</p></div>${db.history.length?historyContent():'<p class="helper-text">ยังไม่มีการอัปเดตอื่น</p>'}`);break;
 case 'clear-filter':filter='all';query='';render();break;
 case 'my-work':closeModal();navigate('work');break;
 case 'start-assessment':if(!$('#assessment-consent').checked){toast('กรุณาอ่านและเลือกความยินยอมก่อนเริ่ม');return}db.profile.name=$('#assess-name').value.trim()||'ผู้เรียน';db.profile.major=$('#assess-major').value.trim()||'ยังสำรวจอยู่';if(db.assessed)db.answers=[];assessmentStarted=true;assessmentStep=0;save();render();break;
 case 'prev-question':if(assessmentStep>0)assessmentStep--;else assessmentStarted=false;render();break;
 case 'next-question':if(!Number.isInteger(db.answers[assessmentStep]))return;if(assessmentStep===questions.length-1)finishAssessment();else{assessmentStep++;render()}break;
 case 'branch-filter':if(filter!=='all'){filter='all';render()}else modal('เลือกกลุ่มเส้นทางที่อยากสำรวจ',`<p class="helper-text">เส้นทางอื่นยังคงอยู่ คุณสามารถกลับมาดูทุกกิ่งได้เสมอ</p><div class="options">${[['creative','สื่อและความคิดสร้างสรรค์'],['business','ธุรกิจและผู้คน'],['tech','ดิจิทัลและข้อมูล']].map(([id,label])=>`<button class="option" data-branch="${id}">${label}${I('arrow')}</button>`).join('')}</div>`);break;
 case 'new-job':newJob();break;
 case 'advisor-note':modal('บันทึกคำแนะนำรายบุคคล',`<form id="advisor-form"><label class="field"><span>คำแนะนำจากอาจารย์ (จำลอง)</span><textarea name="note" maxlength="1000" required>${esc(db.advisorNote||'')}</textarea></label><button class="btn primary" type="submit">บันทึกในต้นแบบ</button></form>`);break;
 case 'export':{const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='higher-my-prototype-data.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('ดาวน์โหลดข้อมูลต้นแบบแล้ว');break}
 case 'reset':modal('เริ่มต้นข้อมูลจำลองใหม่',`<p>จะล้างคำตอบ งานที่สมัคร และประสบการณ์ที่บันทึกในต้นแบบนี้ แล้วกลับไปใช้โปรไฟล์ตัวอย่าง</p><p class="helper-text">คุณดาวน์โหลดข้อมูลไว้ก่อนได้จากหน้าโปรไฟล์</p>`,btn('เก็บข้อมูลไว้',`data-action="close-modal"`)+btn('ยืนยันรีเซ็ตข้อมูล',`data-action="confirm-reset"`,'primary'));break;
 case 'confirm-reset':db=structuredClone(defaults);save();closeModal();selected='content';filter='all';assessmentStarted=false;assessmentStep=0;navigate('roadmap');toast('กลับสู่ข้อมูลตัวอย่างเริ่มต้นแล้ว');break;
 }
 if(t.dataset.branch){filter=t.dataset.branch;closeModal();render()}
});
document.addEventListener('input',e=>{if(e.target.id==='job-search'){query=e.target.value;const list=rankedJobs().filter(j=>(filter==='all'||(filter==='saved'?db.saved.includes(j.id):j.category===filter))&&`${j.title} ${j.company} ${j.subjects}`.toLowerCase().includes(query.toLowerCase()));$('#job-results').innerHTML=list.length?list.map(jobCard).join(''):'<div class="empty"><h3>ไม่พบงานที่ค้นหา</h3><p>ลองเปลี่ยนคำค้นหรือเลือกกลุ่มงานอื่น</p></div>'}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,f=Object.fromEntries(new FormData(form));
 if(form.id==='profile-form'){db.profile={...db.profile,name:f.name.trim()||'ผู้เรียน',institution:f.institution.trim(),major:f.major.trim(),hours:Number(f.hours),mode:f.mode};save();render();toast('บันทึกโปรไฟล์ในเบราว์เซอร์แล้ว')}
 if(form.id==='evidence-form'){const a=appFor(form.dataset.jobId);if(a?.status!=='accepted')return;a.evidence=f.evidence.trim();a.status='submitted';save();closeModal();render();toast('ส่งผลงานจำลองแล้ว ไปหน้าผู้ว่าจ้างเพื่อให้ผลประเมิน')}
 if(form.id==='review-form'){const a=appFor(form.dataset.jobId);if(a?.status!=='submitted')return;a.employerFeedback={rating:feedbackRating,comment:f.comment.trim()};a.status='reviewed';save();closeModal();render();toast('บันทึกผลประเมินแล้ว กลับมุมมองผู้เรียนเพื่อสะท้อนประสบการณ์')}
 if(form.id==='reflection-form'){const a=appFor(form.dataset.jobId);if(a?.status!=='reviewed')return;const j=jobs().find(j=>j.id===a.jobId);a.reflection={feeling:f.feeling,note:f.note.trim()};a.status='completed';a.changes={};db.history.push({date:new Date().toLocaleDateString('th-TH'),title:`ค้นพบตัวเองผ่าน ${j.title}`,text:`${f.feeling} · ${f.note.trim()} · บันทึกผลงานและผลประเมินเป็นหลักฐาน ไม่บวกคะแนนความสามารถแบบคงที่${f.feeling==='อยากสำรวจเส้นทางอื่น'?' ระบบยังเปิดทุกกิ่งและชวนลองงานต่างกลุ่ม':''}`});save();closeModal();selected=j.node||'me';mapView='tree';filter='all';navigate('roadmap');toast('บันทึกประสบการณ์และอัปเดตเส้นทางแล้ว โดยไม่เพิ่มคะแนนความสามารถอัตโนมัติ')}
 if(form.id==='advisor-form'){db.advisorNote=f.note.trim();save();closeModal();render();toast('บันทึกคำแนะนำแล้ว')}
 if(form.id==='new-job-form'){const cat=f.category,keys=cat==='creative'?['creative','communication']:cat==='business'?['team','communication']:['digital','analysis'];db.customJobs.push({id:'job-'+Date.now(),title:f.title.trim(),company:f.company.trim(),initial:f.company.trim().slice(0,2),category:cat,pay:Number(f.pay),unit:'งาน',hours:Number(f.hours),place:f.place,duration:`${f.hours} ชั่วโมง / งาน`,skills:keys.map(k=>skillNames[k]),subjects:cat==='creative'?'การสื่อสารและการออกแบบ':cat==='business'?'การจัดการและการทำงานร่วมกัน':'คอมพิวเตอร์และการวิเคราะห์',description:f.description.trim(),tasks:[f.description.trim()],scores:Object.fromEntries(keys.map(k=>[k,8])),node:cat==='creative'?'creative-base':cat==='business'?'business-base':'tech-base'});save();closeModal();render();toast('เพิ่มงานตัวอย่างแล้ว ผู้เรียนสามารถค้นหาและสมัครได้')}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('#overlay').firstChild){const items=[...$('#overlay').querySelectorAll('button,input,select,textarea,a[href]')].filter(v=>!v.disabled);if(!items.length)return;const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
render();
